import csv
import io


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")
    rows = records[1:]

    # A lone unquoted comment following the header is a report note, not a row.
    physical_lines = raw_csv.splitlines()
    if (
        len(rows) == 1
        and len(rows[0]) == 1
        and len(physical_lines) == 2
        and physical_lines[1].startswith("# ")
    ):
        rows = []

    width = max([len(columns)] + [len(row) for row in rows])
    used_names = set(columns)
    while len(columns) < width:
        number = len(columns) + 1
        name = "column_" + str(number)
        while name in used_names:
            number += 1
            name = "column_" + str(number)
        columns.append(name)
        used_names.add(name)

    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
